contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 reqID_, uint256 loanID_) public payable {
        require(true);

        // Create a loan: the test contract becomes the lender via clearRequest.
        c.requestLoan(1000, 0, 1, 1 days); if (__ESBMC_reverted()) return;
        uint256 loanID = c.clearRequest(reqID_, true, false); if (__ESBMC_reverted()) return;

        // The caller (this test contract) is the lender of loanID.
        bool reverted;
        c.approveTransfer(address(0xdead), loanID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Rule: approveTransfer on an existing loan must NOT revert when the caller is the lender.
        assert(!reverted);
    }

    receive() external payable {}
}

