pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqID_, uint256 loanID_) internal {
        vm.assume(true);
        try c.requestLoan(1000, 0, 1, 1 days) {} catch { return; }
        uint256 loanID;
        try c.clearRequest(reqID_, true, false) returns (uint256 __r) { loanID = __r; } catch { return; }
        bool reverted;
        try c.approveTransfer(address(0xdead), loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted);
    }

    function testFuzz_run(uint256 reqID_, uint256 loanID_) public {
        _run(reqID_, loanID_);
    }

    receive() external payable {}
}
